python3 - <<'PY'
import pytsk3, os
img=pytsk3.Img_Info('inputs/s4a-challenge4')
fs=pytsk3.FS_Info(img, offset=1048576)
for base in ['/inetpub','/xampp','/Program Files']:
    try:
        d=fs.open_dir(base)
    except Exception as e:
        print('ERR',base,e)
        continue
    print('\n##',base)
    def walk(dir_handle, prefix=''):
        for e in dir_handle:
            name=e.info.name.name
            if name in [b'.',b'..']:
                continue
            n=name.decode('utf-8','ignore')
            meta=e.info.meta
            typ=meta.type if meta else None
            path=prefix+'/'+n if prefix else '/'+n
            print(path, 'T'+str(typ) if typ is not None else 'None', 'size', meta.size if meta else None, 'mtime', meta.mtime if meta else None, 'atime', meta.atime if meta else None, 'ctime', meta.ctime if meta else None, 'crtime', meta.crtime if meta else None)
            if meta and meta.type==pytsk3.TSK_FS_META_TYPE_DIR:
                try:
                    walk(fs.open_dir(path), path)
                except Exception as ee:
                    print('  ERR walk',path,ee)
    walk(d,base if base!='/ ' else '')
PY

