from Evtx.Evtx import Evtx
import xml.etree.ElementTree as ET
path='work/extracted/s50bb03/evtx/Security.evtx'
ids={4720,4726,4728,4732,4738,4688,4624,4648}
ns={'e':'http://schemas.microsoft.com/win/2004/08/events/event'}
with Evtx(path) as log:
    for rec in log.records():
        xml=rec.xml().decode('utf-8', 'ignore') if isinstance(rec.xml(), bytes) else rec.xml()
        try:
            root=ET.fromstring(xml)
        except Exception:
            continue
        eid=int(root.findtext('e:System/e:EventID', default='0', namespaces=ns))
        if eid in ids:
            time=root.find('e:System/e:TimeCreated', ns).attrib.get('SystemTime') if root.find('e:System/e:TimeCreated', ns) is not None else ''
            data={d.attrib.get('Name'): (d.text or '') for d in root.findall('e:EventData/e:Data', ns)}
            print('EID', eid, time, data)
