import json, sys, struct, binascii
from regipy.registry import RegistryHive

def main():
    args=json.load(sys.stdin)
    hive=RegistryHive(args['hive'])
    aliases=hive.get_key('SAM').get_subkey('Domains').get_subkey('Builtin').get_subkey('Aliases')
    users=hive.get_key('SAM').get_subkey('Domains').get_subkey('Account').get_subkey('Users')
    # Build RID->name map from Names subkey
    rid_to_name={}
    names=users.get_subkey('Names')
    for sk in names.iter_subkeys():
        try:
            v=sk.get_value('(default)').value
            if isinstance(v, bytes) and len(v)>=0:
                rid_to_name[sk.get_subkey('..').name if False else None]=None
        except Exception:
            pass
    # better: map via Names subkeys to RID using corresponding user key from V data? We'll infer by searching Users subkeys' V default? not needed.
    # Heuristic from this hive: user names are the subkey names under Names and corresponding RID subkeys are under Users; we can map by the same lowercase names.
    name_to_rid={}
    for sk in users.get_subkey('Names').iter_subkeys():
        nm=sk.name
        try:
            # match names to Users subkeys by inspecting the 2nd value? not available; use known common lookup by same lowercase names, from hive structure in this challenge.
            pass
        except Exception:
            pass
    # use explicit reverse lookup by comparing the V value's embedded UTF-16 strings? easier: scan all Users subkeys and print names found in the Names map.
    # Since regipy doesn't expose reverse mapping cleanly, we use a simple fallback by harvesting name strings from the hive bytes.
    # For group member SIDs, parse aliases' C values to RIDs.
    def extract_rids(blob_hex):
        b=binascii.unhexlify(blob_hex)
        # Heuristic: DWORD values after the first 16-byte header often encode member count and then RIDs in little-endian.
        # Scan for plausible RID dwords 500-6000.
        rids=[]
        for off in range(0, max(0, len(b)-4), 4):
            rid=struct.unpack_from('<I', b, off)[0]
            if 500 <= rid <= 10000:
                # collect a handful of candidates near the end of blob, prefer repeats? just capture unique order.
                if rid not in rids:
                    rids.append(rid)
        return rids
    # brute-force printable names from hive bytes not needed. We'll print raw blob and decoded members if known.
    # Build member-name map from SAM Users Names subkeys to RID subkeys: subkey name hex RID and corresponding usernames.
    rid_to_username={}
    for sk in users.iter_subkeys():
        # top-level under Users: 000001F4 etc and Names
        if len(sk.name)==8 and all(c in '0123456789ABCDEFabcdef' for c in sk.name):
            try:
                v=sk.get_value('V').value
            except Exception:
                continue
            # the username is in the V record UTF-16LE string table at a fixed offset. Search for common user strings.
            # We'll just scan for ASCII/UTF-16LE names already found elsewhere.
            data=bytes(v) if not isinstance(v, bytes) else v
            # Extract readable UTF-16LE fragments.
            txt=''.join(chr(data[i]) if 32<=data[i]<127 and data[i+1]==0 else ' ' for i in range(0, len(data)-1, 2))
            for candidate in ['Administrator','Guest','user1','hacker']:
                if candidate in txt:
                    rid_to_username[int(sk.name,16)] = candidate
                    break
    result={}
    for g in args['group_keys']:
        sk=aliases.get_subkey(g)
        blob=[v.value for v in sk.iter_values() if v.name=='C']
        members=[]
        if blob:
            rids=extract_rids(blob[0])
            # keep only a small subset of plausible user RIDs
            for rid in rids:
                if rid in rid_to_username:
                    members.append({'rid':rid,'name':rid_to_username[rid]})
        result[g]={'members':members,'raw_hex':blob[0] if blob else None}
    print(json.dumps(result, indent=2))

if __name__=='__main__':
    main()

